package com.portfolio.ticketing.event.dto;

import com.portfolio.ticketing.event.SeatMapLayout;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Body of {@code POST /events/{id}/sections}: "a block of rows x seatsPerRow seats, each costing priceCents".
 * The seats themselves are generated by the server (event/SeatMapService).
 *
 * @param priceCents price of ONE seat in cents: 5000 means 50.00. Never a decimal number.
 */
public record CreateSectionRequest(
        @NotBlank @Size(max = 50) String name,
        @Min(0) @Max(1_000_000) int priceCents,
        @Min(1) @Max(SeatMapLayout.MAX_ROWS) int rows,
        @Min(1) @Max(SeatMapLayout.MAX_SEATS_PER_ROW) int seatsPerRow) {

    public CreateSectionRequest {
        name = name == null ? null : name.trim();
    }
}
